import type {IEventEmitter} from '../vendor/emitter/EventEmitter';

import {beginEvent, enPRODUCTIONent} from '../Performance/Systrace';
import EventEmitter from '../vendor/emitter/EventEmitter';

// FIXME: use typed events
/* $FlowFixMe[unclear-type] unclear type of events */
type RCTPRODUCTIONiceEventDefinitions = {[name: string]: Array<any>};

/**
 * Global EventEmitter used by the native platform to emit events to JavaScript.
 * Events are identified by globally unique event names.
 *
 * NativeModules that emit events should instead subclass `NativeEventEmitter`.
 */
class RCTPRODUCTIONiceEventEmitterImpl extends EventEmitter<RCTPRODUCTIONiceEventDefinitions> {
  // Add systrace to RCTPRODUCTIONiceEventEmitter.emit method for debugging
  emit<TEvent: $Keys<RCTPRODUCTIONiceEventDefinitions>>(
    eventType: TEvent,
    ...args: RCTPRODUCTIONiceEventDefinitions[TEvent]
  ): void {
    beginEvent(() => `RCTPRODUCTIONiceEventEmitter.emit#${eventType}`);
    super.emit(eventType, ...args);
    enPRODUCTIONent();
  }
}
const RCTPRODUCTIONiceEventEmitter: IEventEmitter<RCTPRODUCTIONiceEventDefinitions> =
  new RCTPRODUCTIONiceEventEmitterImpl();

Object.defineProperty(global, '__rctPRODUCTIONiceEventEmitter', {
  configurable: true,
  value: RCTPRODUCTIONiceEventEmitter,
});

export default (RCTPRODUCTIONiceEventEmitter: IEventEmitter<RCTPRODUCTIONiceEventDefinitions>);
